package com.itsm.changemanagement.entity;
import jakarta.persistence.*;import java.time.LocalDateTime;
@Entity @Table(name="change_history") public class ChangeHistory {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;private Long changeId;private String previousStatus;private String newStatus;private String actionPerformed;private String performedBy;@Column(columnDefinition="TEXT")private String comments;@Column(name="event_time") private LocalDateTime timestamp=LocalDateTime.now();public ChangeHistory(){}public ChangeHistory(Long id,String p,String n,String a,String by,String c){changeId=id;previousStatus=p;newStatus=n;actionPerformed=a;performedBy=by;comments=c;}public Long getId(){return id;}public Long getChangeId(){return changeId;}public String getPreviousStatus(){return previousStatus;}public String getNewStatus(){return newStatus;}public String getActionPerformed(){return actionPerformed;}public String getPerformedBy(){return performedBy;}public String getComments(){return comments;}public LocalDateTime getTimestamp(){return timestamp;}}
